(function(){const src='data:image/jpeg;base64,';function apply(root){(root||document).querySelectorAll('.ac-avatar,.ac-mini-avatar').forEach(el=>{el.textContent='';el.style.setProperty('background','center 38% / cover no-repeat url("'+src+'")','important');el.style.setProperty('color','transparent','important');el.style.setProperty('overflow','hidden','important');el.style.setProperty('border-radius','50%','important');});document.querySelectorAll('#ariellaDesktopChat .ariella-new-chat').forEach(el=>el.remove());}function boot(){apply(document);new MutationObserver(()=>apply(document)).observe(document.body,{childList:true,subtree:true});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();